export const RARITY_ORDER = ['common', 'magic', 'rare', 'legendary', 'mythic'];

let itemCounter = 0;

export function rarityRank(key) {
  return RARITY_ORDER.indexOf(key);
}

export function rarityInfo(key) {
  return RARITIES[key] || RARITIES.common;
}

export function rollRarity(rng, { luck = 0, minRarity = 'common' } = {}) {
  const min = rarityRank(minRarity);
  const luckScale = 1 + Math.max(0, luck) / 100;
  const entries = [
    { value: 'common', weight: 1000 },
    { value: 'magic', weight: 350 * Math.pow(luckScale, 0.55) },
    { value: 'rare', weight: 88 * Math.pow(luckScale, 1.15) },
    { value: 'legendary', weight: 20 * Math.pow(luckScale, 1.8) },
    { value: 'mythic', weight: 2.6 * Math.pow(luckScale, 2.5) },
  ].filter((entry) => rarityRank(entry.value) >= min);
  return weightedPick(rng, entries);
}

export function affixValue(stat, min, max, ilvl, rarityKey, rng) {
  const levelScale = 1 + Math.max(0, ilvl - 1) * 0.082;
  const rarityScale = RARITIES[rarityKey]?.mult || 1;
  let value = rand(rng, min, max) * levelScale * rarityScale;
  if (stat === 'regen') value = Math.round(value * 10) / 10;
  else if (STAT_DEFS[stat]?.pct) value = Math.round(value);
  else value = Math.max(1, Math.round(value));
  return value;
}

export function formatAffix(affix) {
  const def = STAT_DEFS[affix.stat] || { label: affix.stat, suffix: '' };
  const value = def.flat ? `+${affix.value}` : `+${affix.value}${def.suffix || ''}`;
  return `${def.label} ${value}`;
}

function makeName(rng, slot, rarityKey, affixes) {
  const base = pick(rng, BASE_NAMES[slot]);
  if (rarityKey === 'common') return base;
  const primary = affixes[0]?.stat;
  const prefixes = PREFIXES[primary] || ['Pale'];
  const prefix = pick(rng, prefixes);
  if (rarityKey === 'magic') return `${prefix} ${base}`;
  const suffix = pick(rng, SUFFIXES);
  return `${prefix} ${base} ${suffix}`;
}

export function itemScore(item) {
  if (!item) return 0;
  let score = 0;
  for (const affix of item.affixes || []) {
    const def = STAT_DEFS[affix.stat];
    score += (def?.weight || 1) * affix.value;
  }
  if (item.legendary) score += 24;
  return Math.round(score);
}

export function generateItem(rng, options = {}) {
  const slot = options.slot || pick(rng, SLOTS);
  const ilvl = Math.max(1, Math.round(options.ilvl || 1));
  const rarityKey = options.rarity || rollRarity(rng, { luck: options.luck || 0, minRarity: options.minRarity || 'common' });
  const rarity = RARITIES[rarityKey] || RARITIES.common;
  const pool = SLOT_AFFIXES[slot].slice();
  const affixes = [];
  const count = Math.min(rarity.affixes, pool.length);

  for (let i = 0; i < count; i++) {
    const chosen = weightedPick(rng, pool.map((entry) => ({ value: entry, weight: entry.weight })));
    const index = pool.indexOf(chosen);
    pool.splice(index, 1);
    affixes.push({
      stat: chosen.stat,
      value: affixValue(chosen.stat, chosen.min, chosen.max, ilvl, rarityKey, rng),
    });
  }

  let legendary = null;
  if (rarityKey === 'legendary' || rarityKey === 'mythic') {
    legendary = pick(rng, LEGENDARY_POWERS);
  }

  itemCounter = (itemCounter + 1) % 100000;
  const item = {
    id: `it_${itemCounter}_${Math.floor(rng() * 1e9).toString(36)}`,
    slot,
    rarity: rarityKey,
    ilvl,
    affixes,
    legendary,
    name: makeName(rng, slot, rarityKey, affixes),
  };
  item.score = itemScore(item);
  return item;
}

export function aggregateStats(items) {
  const totals = {};
  for (const item of items) {
    if (!item) continue;
    for (const affix of item.affixes) {
      totals[affix.stat] = (totals[affix.stat] || 0) + affix.value;
    }
  }
  return totals;
}

export function hasPower(items, id) {
  return items.some((item) => item?.legendary?.id === id);
}

export function statDisplay(stat, value, signed = true) {
  const def = STAT_DEFS[stat] || { label: stat, suffix: '' };
  const sign = signed ? (value >= 0 ? '+' : '') : '';
  return `${sign}${value}${def.suffix || ''}`;
}

export function rarityCounts(items) {
  const counts = { common: 0, magic: 0, rare: 0, legendary: 0, mythic: 0 };
  for (const item of items) {
    if (item && counts[item.rarity] !== undefined) counts[item.rarity]++;
  }
  return counts;
}

export function compareItemToEquipped(item, equipped) {
  const mine = item ? item.score : 0;
  const theirs = equipped ? equipped.score : 0;
  return { power: mine, equippedPower: theirs, delta: mine - theirs };
}

// Tiny procedural audio engine — every sound is synthesized, no assets.

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.last = new Map();
    this.noiseBuffer = null;
    this.ambientStarted = false;
    try {
      this.muted = localStorage.getItem('gravebound-muted') === '1';
    } catch { /* storage unavailable */ }
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.45;
    this.master.connect(this.ctx.destination);
    this.noiseBuffer = this.makeNoise(2);
    this.startAmbient();
  }

  makeNoise(seconds) {
    const buffer = this.ctx.createBuffer(1, Math.floor(this.ctx.sampleRate * seconds), this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.45, this.ctx.currentTime, 0.08);
    }
    try { localStorage.setItem('gravebound-muted', muted ? '1' : '0'); } catch { /* ignore */ }
  }

  toggleMuted() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  ready() {
    return this.ctx && this.ctx.state === 'running' && !this.muted;
  }

  throttle(key, ms) {
    const now = performance.now();
    const prev = this.last.get(key) || 0;
    if (now - prev < ms) return false;
    this.last.set(key, now);
    return true;
  }

  tone({ freq = 220, to = null, dur = 0.15, type = 'sine', gain = 0.12, delay = 0, attack = 0.005, filter = null }) {
    if (!this.ready()) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const g = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (to) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(gain, t0 + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    let node = osc;
    if (filter) {
      const f = ctx.createBiquadFilter();
      f.type = filter.type || 'lowpass';
      f.frequency.value = filter.freq || 900;
      f.Q.value = filter.q || 1;
      osc.connect(f);
      node = f;
    }
    node.connect(g);
    g.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  noise({ dur = 0.12, gain = 0.08, freq = 1200, type = 'bandpass', q = 1, to = null, delay = 0 }) {
    if (!this.ready()) return;
    const ctx = this.ctx;
    const t0 = ctx.currentTime + delay;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t0);
    if (to) f.frequency.exponentialRampToValueAtTime(Math.max(40, to), t0 + dur);
    f.Q.value = q;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t0);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    src.connect(f).connect(g).connect(this.master);
    src.start(t0);
    src.stop(t0 + dur + 0.02);
  }

  startAmbient() {
    if (this.ambientStarted || !this.ctx) return;
    this.ambientStarted = true;
    const ctx = this.ctx;
    const amb = ctx.createGain();
    amb.gain.value = 0.035;
    amb.connect(this.master);

    const low = ctx.createOscillator();
    low.type = 'sawtooth';
    low.frequency.value = 41.2;
    const lowFilter = ctx.createBiquadFilter();
    lowFilter.type = 'lowpass';
    lowFilter.frequency.value = 130;
    const lowGain = ctx.createGain();
    lowGain.gain.value = 0.7;
    low.connect(lowFilter).connect(lowGain).connect(amb);
    low.start();

    const fifth = ctx.createOscillator();
    fifth.type = 'triangle';
    fifth.frequency.value = 61.7;
    const fifthGain = ctx.createGain();
    fifthGain.gain.value = 0.22;
    fifth.connect(fifthGain).connect(amb);
    fifth.start();

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.07;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.012;
    lfo.connect(lfoGain).connect(amb.gain);
    lfo.start();

    const wind = ctx.createBufferSource();
    wind.buffer = this.noiseBuffer;
    wind.loop = true;
    const windFilter = ctx.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 360;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.02;
    wind.connect(windFilter).connect(windGain).connect(this.master);
    wind.start();
  }

  swing() {
    if (!this.throttle('swing', 90)) return;
    this.noise({ dur: 0.18, gain: 0.05, freq: 2400, to: 380, type: 'bandpass', q: 1.6 });
  }

  bolt() {
    if (!this.throttle('bolt', 70)) return;
    this.tone({ freq: 720, to: 220, dur: 0.13, type: 'triangle', gain: 0.055 });
    this.tone({ freq: 1080, to: 540, dur: 0.09, type: 'sine', gain: 0.025 });
  }

  hit(crit = false) {
    if (!this.throttle(crit ? 'crit' : 'hit', 42)) return;
    this.noise({ dur: crit ? 0.1 : 0.07, gain: crit ? 0.075 : 0.035, freq: crit ? 1800 : 800, to: 200, type: 'bandpass', q: 0.8 });
    if (crit) this.tone({ freq: 130, to: 70, dur: 0.1, type: 'square', gain: 0.03 });
  }

  hurt() {
    if (!this.throttle('hurt', 220)) return;
    this.tone({ freq: 110, to: 48, dur: 0.28, type: 'sawtooth', gain: 0.08, filter: { type: 'lowpass', freq: 500 } });
    this.noise({ dur: 0.2, gain: 0.05, freq: 500, to: 100, type: 'lowpass' });
  }

  gem() {
    if (!this.throttle('gem', 55)) return;
    this.tone({ freq: 1250 + Math.random() * 250, to: 1700, dur: 0.055, type: 'sine', gain: 0.018 });
  }

  pickup(rarity = 'common') {
    const rank = { common: 0, magic: 1, rare: 2, legendary: 3, mythic: 4 }[rarity] ?? 0;
    const notes = [523.25, 659.25, 783.99, 1046.5, 1318.5];
    const count = 2 + rank;
    for (let i = 0; i < count; i++) {
      this.tone({ freq: notes[i % notes.length] * (i >= notes.length ? 0.5 : 1), dur: 0.2, type: 'triangle', gain: 0.045, delay: i * 0.055 });
    }
    if (rank >= 3) {
      this.tone({ freq: 65.4, dur: 1.1, type: 'sawtooth', gain: 0.05, filter: { type: 'lowpass', freq: 300 } });
      this.tone({ freq: 164.8, dur: 0.9, type: 'sine', gain: 0.05, delay: 0.12 });
    }
  }

  levelup() {
    const notes = [261.63, 329.63, 392, 523.25, 659.25];
    notes.forEach((freq, i) => this.tone({ freq, dur: 0.7, type: 'triangle', gain: 0.04, delay: i * 0.08 }));
    this.tone({ freq: 65.4, dur: 1.2, type: 'sine', gain: 0.07 });
  }

  heal() {
    this.tone({ freq: 440, to: 660, dur: 0.3, type: 'sine', gain: 0.035 });
  }

  boss() {
    if (!this.throttle('boss', 1000)) return;
    this.tone({ freq: 55, to: 36, dur: 1.8, type: 'sawtooth', gain: 0.1, filter: { type: 'lowpass', freq: 240 } });
    this.noise({ dur: 1.4, gain: 0.06, freq: 240, to: 60, type: 'lowpass' });
    for (let i = 0; i < 3; i++) this.tone({ freq: 110 * (i + 1), dur: 1.5, type: 'triangle', gain: 0.02, delay: 0.2 + i * 0.3 });
  }

  death() {
    const notes = [392, 329.63, 261.63, 196, 130.81];
    notes.forEach((freq, i) => this.tone({ freq, dur: 0.8, type: 'triangle', gain: 0.05, delay: i * 0.14 }));
  }

  victory() {
    const notes = [261.63, 329.63, 392, 523.25, 783.99, 1046.5];
    notes.forEach((freq, i) => this.tone({ freq, dur: 1.4, type: 'triangle', gain: 0.045, delay: i * 0.12 }));
  }

  click() {
    this.tone({ freq: 620, to: 480, dur: 0.07, type: 'triangle', gain: 0.03 });
  }
}

// Procedural sprite & environment art. Everything is drawn once into offscreen
// canvases at 2x and blitted at runtime, which keeps hundreds of enemies cheap.

import { mulberry32, pick, rand } from './rng.js';

function makeCanvas(w, h) {
  const c = document.createElement('canvas');
  c.width = Math.ceil(w);
  c.height = Math.ceil(h);
  return c;
}

function layer(w, h, draw, scale = 2) {
  const c = makeCanvas(w * scale, h * scale);
  const ctx = c.getContext('2d');
  ctx.scale(scale, scale);
  draw(ctx, w, h);
  return c;
}

function ellipse(ctx, x, y, rx, ry, fill) {
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
  ctx.fillStyle = fill;
  ctx.fill();
}

function glowDot(ctx, x, y, r, color) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, color);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fill();
}

