  ctx.strokeStyle = bone;
  ctx.lineWidth = 4;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(-6, 8); ctx.lineTo(-10, 18); ctx.lineTo(-8, 30);
