glowFor(color) {
  let key = color;
  if (color.startsWith('#')) {
    const { r, g, b } = hexToRgb(color);
    key = `${r},${g},${b}`;
  }
  let glow = this.glows.get(key);
  if (!glow) {
    glow = makeGlow(128, key);
    this.glows.set(key, glow);
  }
  return glow;
}

