input.newString:
drawLootIcons(game, cam) {
  const ctx = this.ctx;
  const drops = game.state === 'title' ? game.titleLoot : game.loot;
  const halfW = this.w / 2 + 120;
  const halfH = this.h / 2 + 120;
  const visible = drops.filter(
    (d) => Math.abs(d.x - cam.x) <= halfW && Math.abs(d.y - cam.y) <= halfH,
  );

  // Draw icons first; labels are laid out afterwards so they can dodge each other.
  for (const drop of visible) {
    const info = rarityInfo(drop.item.rarity);
    const icon = this.iconFor(drop.item);
    const bob = Math.sin(this.time * 2.1 + drop.bob) * 4;
    const y = drop.y - 16 + bob;
    ctx.save();
    ctx.globalAlpha = 0.35;
    ctx.fillStyle = '#000';
    ctx.beginPath();
    ctx.ellipse(drop.x, drop.y + 8, 14, 5, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
    ctx.drawImage(icon, drop.x - 18, y - 18, 36, 36);
    // sparkle orbit
    const angle = this.time * 1.6 + drop.bob;
    ctx.fillStyle = info.color;
    ctx.globalAlpha = 0.75;
    ctx.beginPath();
    ctx.arc(drop.x + Math.cos(angle) * 23, y + Math.sin(angle) * 10, 1.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // Only a handful of labels at once, prioritising high rarity and proximity.
  const rarityRank = { mythic: 5, legendary: 4, rare: 3, magic: 2, common: 1 };
  const labelled = visible
    .filter((drop) => !drop.preview)
    .map((drop) => ({
      drop,
      dist: Math.hypot(drop.x - game.player.x, drop.y - game.player.y),
    }))
    .filter((entry) => entry.dist < 300)
    .sort((a, b) => {
      const r = (rarityRank[b.drop.item.rarity] || 0) - (rarityRank[a.drop.item.rarity] || 0);
      return r !== 0 ? r : a.dist - b.dist;
    })
    .slice(0, 4);

  const placed = [];
  for (const { drop } of labelled) {
    const info = rarityInfo(drop.item.rarity);
    const bob = Math.sin(this.time * 2.1 + drop.bob) * 4;
    const baseY = drop.y - 48 + bob;
    ctx.font = '600 10px "Segoe UI", system-ui, sans-serif';
    const textWidth = ctx.measureText(drop.item.name).width;
    const width = textWidth + 12;
    let y = baseY;
    for (let guard = 0; guard < 8; guard++) {
      const hit = placed.find(
        (r) => Math.abs(r.x - drop.x) < (r.w + width) / 2 + 4 && Math.abs(r.y - y) < 23,
      );
      if (!hit) break;
      y = hit.y - 23;
    }
    placed.push({ x: drop.x, y, w: width });

    ctx.save();
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(6,4,10,0.8)';
    ctx.beginPath();
    ctx.roundRect(drop.x - width / 2, y - 12, width, 16, 3);
    ctx.fill();
    ctx.strokeStyle = `${info.color}55`;
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.fillStyle = info.color;
    ctx.fillText(drop.item.name, drop.x, y);
    ctx.font = '700 7px "Segoe UI", system-ui, sans-serif';
    ctx.fillStyle = 'rgba(233,225,207,0.55)';
    ctx.fillText(`${info.label.toUpperCase()} · POWER ${drop.item.score}`, drop.x, y - 15);
    // tether from label stack back to the item so the pairing stays clear
    ctx.strokeStyle = `${info.color}44`;
    ctx.beginPath();
    ctx.moveTo(drop.x, y + 4);
    ctx.lineTo(drop.x, drop.y - 26 + bob);
    ctx.stroke();
    ctx.restore();
  }
}

