210:   const slot = options.slot || pick(rng, SLOTS);
211:   const ilvl = Math.max(1, Math.round(options.ilvl || 1));
212:   const rarityKey = options.rarity || rollRarity(rng, { luck: options.luck || 0, minRarity: options.minRarity || 'common' });
213:   const rarity = RARITIES[rarityKey] || RARITIES.common;
214:   const pool = SLOT_AFFIXES[slot].slice();
215:   const affixes = [];
216:   const count = Math.min(rarity.affixes, pool.length);
217: 
218:   for (let i = 0; i < count; i++) {
219:     const chosen = weightedPick(rng, pool.map((entry) => ({ value: entry, weight: entry.weight })));
220:     const index = pool.indexOf(chosen);
221:     pool.splice(index, 1);
222:     affixes.push({
223:       stat: chosen.stat,
224:       value: affixValue(chosen.stat, chosen.min, chosen.max, ilvl, rarityKey, rng),
225:     });
226:   }
227: 
228:   let legendary = null;
229:   if (rarityKey === 'legendary' || rarityKey === 'mythic') {
230:     legendary = pick(rng, LEGENDARY_POWERS);
231:   }
232: 
233:   itemCounter = (itemCounter + 1) % 100000;
234:   const item = {
235:     id: `it_${itemCounter}_${Math.floor(rng() * 1e9).toString(36)}`,
236:     slot,
237:     rarity: rarityKey,
238:     ilvl,
239:     affixes,
240:     legendary,
241:     name: makeName(rng, slot, rarityKey, affixes),
242:   };
243:   item.score = itemScore(item);
244:   return item;
245: }
246: 
247: export function aggregateStats(items) {
248:   const totals = {};
249:   for (const item of items) {
250:     if (!item) continue;
251:     for (const affix of item.affixes) {
252:       totals[affix.stat] = (totals[affix.stat] || 0) + affix.value;
253:     }
254:   }
255:   return totals;
256: }
257: 
258: export function hasPower(items, id) {
259:   return items.some((item) => item?.legendary?.id === id);
260: }
261: 
262: export function statDisplay(stat, value, signed = true) {
263:   const def = STAT_DEFS[stat] || { label: stat, suffix: '' };
264:   const sign = signed ? (value >= 0 ? '+' : '') : '';
265:   return `${sign}${value}${def.suffix || ''}`;
266: }
267: 
268: export function rarityCounts(items) {
269:   const counts = { common: 0, magic: 0, rare: 0, legendary: 0, mythic: 0 };
270:   for (const item of items) {
271:     if (item && counts[item.rarity] !== undefined) counts[item.rarity]++;
272:   }
273:   return counts;
274: }
275: 
276: export function compareItemToEquipped(item, equipped) {
277:   const mine = item ? item.score : 0;
278:   const theirs = equipped ? equipped.score : 0;
279:   return { power: mine, equippedPower: theirs, delta: mine - theirs };
280: }

